// The main button styles: Generated by Claude Opus 5.5
import React from 'react';
import { Pressable, StyleProp, Text, View, ViewStyle } from 'react-native';
import { ArrowLeftIcon, ArrowRightIcon, EyeIcon, EyeOffIcon } from './icons';
import { HardShadow } from './decor';
import { Theme, fonts, spacing } from '../constants/theme';

// 'primary' = orange (Log in, Publish), 'plain' = white (bell, back, secondary actions)
export type ButtonVariant = 'primary' | 'plain';

// Passed to children 
export type ButtonState = {
  inactive: boolean;  // disabled or loading
  loading: boolean;
  textColor: string;  // for text and icons inside the button
};

export type ThemedButtonProps = {
  onPress: () => void;
  theme: Theme;
  variant?: ButtonVariant;
  disabled?: boolean;
  loading?: boolean;
  accessibilityLabel?: string;
  shadowOffset?: number;          // 5 for big buttons, 3 for small square ones
  shawdowOn?: boolean;
  style?: StyleProp<ViewStyle>;   // size and layout of the button box
  children: React.ReactNode | ((state: ButtonState) => React.ReactNode);
};

// The shared shell: border, background, hard shadow, press effect, disabled/loading.
export function ThemedButton({
  onPress,
  theme,
  variant = 'primary',
  disabled = false,
  loading = false,
  accessibilityLabel,
  shadowOffset = spacing.shadow,
  shawdowOn = true,
  style,
  children,
}: ThemedButtonProps) {
  const inactive = disabled || loading;
  const background = inactive ? theme.disabled : variant === 'primary' ? theme.primary : theme.card;
  const textColor = inactive ? theme.ink : variant === 'primary' ? theme.onPrimary : theme.ink;
  const push = Math.min(3, shadowOffset); // how far the button moves into its shadow when pressed

  return (
    // Disabled buttons sit flat (transparent shadow) but keep the same spacing,
    // so nothing jumps when the button enables.
    <HardShadow offset={shadowOffset} color={inactive || !shawdowOn ? 'transparent' : theme.ink}>
      <Pressable
        onPress={onPress}
        disabled={inactive}
        accessibilityRole="button"
        accessibilityLabel={accessibilityLabel}
        accessibilityState={{ disabled: inactive, busy: loading }}
        style={({ pressed }) => [
          {
            flexDirection: 'row',
            backgroundColor: background,
            borderWidth: theme.borderWidth,
            borderColor: theme.ink,
            transform: pressed && !inactive ? [{ translateX: push }, { translateY: push }] : [],
          },
          style,
        ]}
      >
        {typeof children === 'function' ? children({ inactive, loading, textColor }) : children}
      </Pressable>
    </HardShadow>
  );
}

type ArrowButtonProps = Omit<ThemedButtonProps, 'children' | 'style'> & {
  label?: string;
  direction?: 'forward' | 'back';
  fontsize ?: number;
};

export function ArrowButton({ label, direction = 'forward', fontsize = 20, accessibilityLabel, ...rest }: ArrowButtonProps) {
  const { theme } = rest;
  const hasLabel = !!label;
  const back = direction === 'back';

  return (
    <ThemedButton
      {...rest}
      accessibilityLabel={accessibilityLabel ?? label}
      style={{ minHeight: spacing.buttonHeight, flexDirection: back ? 'row-reverse' : 'row' }}
    >
      {({ loading, textColor }) => (
        <>
          {hasLabel ? (
            <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 12 }}>
              <Text
                style={{
                  fontFamily: fonts.label,
                  fontSize: fontsize,
                  letterSpacing: 1.2,
                  textTransform: 'uppercase',
                  color: textColor,
                }}
              >
                {loading ? 'One sec…' : label}
              </Text>
            </View>
          ) : null}
          <View
            style={{
              width: spacing.arrowBlock,
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: back ? theme.card : theme.arrowBg,
              borderLeftWidth: hasLabel && !back ? theme.borderWidth : 0,
              borderRightWidth: hasLabel && back ? theme.borderWidth : 0,
              borderColor: theme.ink,
            }}
          >
            {back ? <ArrowLeftIcon color={theme.ink} /> : <ArrowRightIcon color={theme.arrowFg} />}
          </View>
        </>
      )}
    </ThemedButton>
  );
}

type IconButtonProps = Omit<ThemedButtonProps, 'children' | 'style' | 'accessibilityLabel'> & {
  accessibilityLabel: string;               // required: an icon alone says nothing to screen readers
  icon: (color: string) => React.ReactNode; // gets the right color for the button's state
  size?: number;
};

export function IconButton({ icon, size = 48, variant = 'plain', shadowOffset = 3, ...rest }: IconButtonProps) {
  return (
    <ThemedButton
      {...rest}
      variant={variant}
      shadowOffset={shadowOffset}
      style={{width: size,  minHeight: spacing.buttonHeight, alignItems: 'center', justifyContent: 'center' }}
    >
      {({ textColor }) => icon(textColor)}
    </ThemedButton>
  );
}

type FilterChipProps = {
  label: string;
  selected: boolean;
  onPress: () => void;
  theme: Theme;
};

export function FilterChip({ label, selected, onPress, theme }: FilterChipProps) {
  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityState={{ selected }}
      accessibilityLabel={label}
      style={({ pressed }) => ({
        minHeight: 35,
        paddingHorizontal: 12,
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: selected ? theme.ink : theme.card,
        borderWidth: theme.borderWidth,
        borderColor: theme.ink,
        opacity: pressed && !selected ? 0.7 : 1,
      })}
    >
      <Text
        style={{
          fontFamily: fonts.label,
          fontSize: 13,
          letterSpacing: 1,
          textTransform: 'uppercase',
          color: selected ? theme.card : theme.ink,
        }}
      >
        {label}
      </Text>
    </Pressable>
  );
}


export function EyeButton({onPress, toggle}:
    {onPress: ()=>void, toggle: boolean}) {
    return (
    <Pressable accessibilityLabel={toggle? 'Show Password': 'Hide Password'}
        accessibilityRole='button'
        style={{
        width: 52,
        borderLeftWidth: 4,
        justifyContent: "center",
        alignItems: "center"
        }} 
        onPress={onPress}>
        {toggle ? <EyeIcon/> : <EyeOffIcon/>}
    </Pressable>);
}
